# Made by Claude (2026-10-20). One-time edit: Files sorted by origin and kind together, Generated by model (and All),
# an icon in its own colour for every kind of file, videos in Collider's player, songs in the music bar.
import os
root = os.path.join(os.path.dirname(__file__), "..")


def edit(rel, pairs):
    p = os.path.join(root, rel)
    s = open(p, encoding="utf-8").read()
    for a, b in pairs:
        if s.count(a) != 1:
            raise SystemExit(f"{rel}: expected one of {a!r}, found {s.count(a)}")
        s = s.replace(a, b)
    open(p, "w", encoding="utf-8", newline="").write(s)


